// TH18 v1.00a Stage 5 MainSub05 -> Phantom01 wave.
// Source: st05.ecl.txt:1136-1157 (spawn schedule), 1278-1296 (Phantom01 main),
//         1298-1351 (Phantom01_at emitter/EX).
// Source t0 is the first MainSub05 spawn; the practice shell adds a 120-frame buffer.
const TIME_LIMIT: int = 1800;   // 120 buffer + 1680 active/tail estimate (source has no timer)
const TH18_BALL2: int = 432;    // source type 5, base radius 4, color 6 (S:1304)

// S:1310-1321: H/L only add WAIT40 then VELTIME80 to the rank speed.
// VELTIME raises the scalar speed while preserving the bullet direction.
xformdef PHANTOM_VEL(target: fx) {
    wait(40);
    step_speed(target, 80);
}

// One Phantom01. All motion is evaluated per source frame from the source layers:
// ABS = moveVel(-90deg, 0.1) ramped by moveVelTime(120, mode0) to ~1.0,
// REL = moveEllipseRel(random phase, 2deg/frame, r10, d0, beta=-90deg, s0).
async sub phantom() {
    set_invuln(65535);
    set_hitbox(8fx);    // S:1282 setHitbox(16) -> target radius 8
    set_hurtbox(14fx);  // S:1282 setHurtbox(28) -> target radius 14

    var rank: int = global(GVAR_RANK);
    var shots: int = 1;       // S:1333 diffI A: 1 for E, 60 otherwise
    var gap: int = 120;       // S:1339-1345 E/N 120, H 60, L 30
    var pre: int = 120;       // S:1323-1331 first rank wait after the initial wait
    if rank > 0 { shots = 60; pre = 10; }
    if rank >= 2 { gap = 60; }
    if rank == 3 { gap = 30; }
    var target_speed: fx = 0fx; // S:1312-1319: H 2.5, L 3.0; E/N keep 1.0
    if rank == 2 { target_speed = 2.5fx; }
    if rank == 3 { target_speed = 3.0fx; }

    // S:1301 initial wait 60+rand%120; the async task first runs one frame after spawn.
    var next_fire: int = pre + 60 + rand(65536)%120;
    var fired: int = 0;

    // S:1285-1287 entry snapshots: RANDF2 for the +-10deg ABS turn,
    // RANDRAD for the REL phase, beta remains the -90deg ABS angle at set time.
    var da: int = ((rand(65536)-32768) * 1820) / 32768;
    var phase0: int = rand(65536);
    var ax: fx = $self_x;
    var ay: fx = $self_y;
    var a: int = -16384;
    var speed: fx = 0.1fx;

    // Turn setup sampled at S:1289 after wait(300).
    var turn_base: int = 0;
    var turn_delta: int = 0;

    var t: int = 0;
    loop {
        // Advance the ABS layer for source movement tick t (source moves before ECL).
        if t > 0 {
            if t <= 120 {
                a = -16384 + da*t/120;                              // S:1286 linear angle
                speed = 0.1fx + 0.9fx*(t as fx)/120;                // S:1286 linear speed
            } else if t <= 300 {
                a = -16384 + da;
                speed = 1fx;
            } else if t <= 420 {
                a = turn_base + turn_delta*(t-300)/120;             // S:1289 shortest-arc turn
                speed = 1fx;
            } else {
                a = turn_base + turn_delta;
                speed = 1fx;
            }
            ax = ax + cos(a as angle)*speed;
            ay = ay + sin(a as angle)*speed;
        }

        // S:1287 REL ellipse: beta=-90deg, s=0 => only x = r*cos(theta); theta += 2deg/tick.
        var rel: fx = 10fx*cos((phase0 + 364*t) as angle);
        var px: fx = ax + rel;
        var py: fx = ay;
        move_to(0, px, py, EASE_LINEAR);

        // S:1289-1290 after 300 frames, sample player direction + RANDF2*10deg once.
        if t == 300 {
            turn_base = -16384 + da;
            var target: int = (atan2($player_y-py, $player_x-px) as int)
                + ((rand(65536)-32768) * 1820) / 32768;
            turn_delta = target - turn_base;
            if turn_delta > 32768 { turn_delta = turn_delta - 65536; }
            if turn_delta < -32768 { turn_delta = turn_delta + 65536; }
        }

        // S:1298-1351 emitter: the goto enters the loop test, so every shot executes
        // S:1336 etAngle(player) before etOn; the initial 0deg setting is overwritten.
        if t == next_fire && fired < shots {
            var fa: angle = atan2($player_y-py, $player_x-px);
            // S:1309 ANIM a=1 retreats 4*velocity at birth (policy keeps this displacement).
            var sx: fx = px - 4fx*cos(fa);
            var sy: fx = py - 4fx*sin(fa);
            if rank >= 2 {
                _ = fire(TH18_BALL2, 6, sx, sy, 1fx, fa, PHANTOM_VEL(target_speed), none);
            } else {
                _ = fire(TH18_BALL2, 6, sx, sy, 1fx, fa, none, none);
            }
            fired = fired + 1;
            next_fire = next_fire + gap;
        }

        wait(1);
        t = t + 1;
    }
}

// S:1136-1157: four iterations, each with four pairs 30 frames apart.
sub spawn_pair(base: fx) {
    // S:1142 etc: base + RANDF2*32, y=448, one independent draw per enemy.
    var jitter: fx = ((rand(65536)-32768) as fx) * 32fx / 32768;
    _ = spawn_enemy(base + jitter, 448fx, 100000, 0, 0, 0, phantom);
}

async sub wave() {
    wait(120); // practice-shell buffer; source t0 is the first spawn below
    for it in 0..3 {
        spawn_pair(-160fx);
        spawn_pair(160fx);
        wait(30);
        spawn_pair(-140fx);
        spawn_pair(140fx);
        wait(30);
        spawn_pair(-110fx);
        spawn_pair(110fx);
        wait(30);
        spawn_pair(-140fx);
        spawn_pair(140fx);
        wait(30);
    }
}

async sub control() {
    set_invuln(65535);
    set_hitbox(0fx);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 100000, 0, 0, 0, control);
    loop { wait(600); }
}
